<?php require_once __DIR__.'/includes/auth.php'; require_login(['admin']);
$pdo=db(); $courses=$pdo->query("SELECT * FROM courses WHERE is_active=1 ORDER BY level,semester,course_code")->fetchAll(); $sessionDefault=setting('active_session','2026/2027'); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$courseId=(int)($_POST['course_id']??0);$session=trim($_POST['session_name']??$sessionDefault);$scripts=max(0,(int)($_POST['number_of_scripts']??0));
 $chk=$pdo->prepare('SELECT * FROM courses WHERE id=? AND is_active=1');$chk->execute([$courseId]);$course=$chk->fetch();
 if(!$course || !$session){$error='Please choose a valid course and session.';}else{try{$pdo->beginTransaction();$token=public_token();$now=date('Y-m-d H:i:s');$pdo->prepare('INSERT INTO result_records(tracking_no,public_token,course_id,session_name,number_of_scripts,current_stage_id,current_office_id,current_since,received_at,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute(['TEMP-'.$token,$token,$courseId,$session,$scripts,1,1,$now,$now,current_user()['id']]);$id=(int)$pdo->lastInsertId();$tracking=make_tracking_no($id);$pdo->prepare('UPDATE result_records SET tracking_no=? WHERE id=?')->execute([$tracking,$id]);$pdo->prepare('INSERT INTO result_movements(result_id,from_stage_id,to_stage_id,from_office_id,to_office_id,handed_over_by,received_by,remarks,user_id) VALUES (?,?,?,?,?,?,?,?,?)')->execute([$id,null,1,null,1,current_user()['name'],current_user()['name'],'Result received from lecturer',current_user()['id']]);$pdo->commit();log_activity($id,'Received from Lecturer','Initial result receipt',current_user()['name']);send_notification($id,'Result Received');flash('success','Result recorded successfully. Tracking number: '.$tracking);redirect('acknowledgement.php?id='.$id);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not save the result. '.$e->getMessage();}}
}
$pageTitle='Record Result | IFT';require __DIR__.'/includes/header.php';?><body class="portal-page"><header class="portal-header"><div class="portal-brand"><img src="assets/naits-logo.png"><div><strong>IFT Result Tracking</strong><span>Secretary / Admin Portal</span></div></div><a class="portal-back" href="admin-dashboard.php">← Dashboard</a></header><main class="form-main"><div class="page-title"><div><span class="kicker">NEW RECORD</span><h1>Record Received Result</h1><p>Create the tracking record when a physical result is received from a lecturer.</p></div></div><?php if($error):?><div class="danger-box"><?=e($error)?></div><?php endif;?><form class="panel form-panel" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-section"><h2>Course details</h2><div class="form-grid"><label>Course<select name="course_id" id="course_id" required><option value="">Select course</option><?php foreach($courses as $c):?><option value="<?=$c['id']?>"><?=e($c['course_code'].' — '.$c['course_title'].' | '.$c['level'].' Level | '.$c['semester'])?></option><?php endforeach;?></select></label><label>Session<input name="session_name" value="<?=e($sessionDefault)?>" placeholder="2026/2027" required></label><label>Number of Scripts<input name="number_of_scripts" type="number" min="0" value="0"></label></div></div><div class="notice">The two lecturers assigned to the selected course are automatically attached to the tracking record. The initial stage is automatically set to <strong>Received from Lecturer</strong>.</div><div class="form-actions"><a class="secondary-btn" href="admin-dashboard.php">Cancel</a><button class="primary-btn" type="submit">Save Result Record</button></div></form></main><?php require __DIR__ . '/includes/footer.php'; ?>
